recipes.code:
{
  "inputs": [
    {
      "id": "promptot-api-key",
      "type": "promptString",
      "description": "Scoped API key from the PromptOT dashboard (Settings > API Keys)",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@prompt-ot/mcp@0.1.2"
      ],
      "env": {
        "PROMPTOT_API_KEY": "${input:promptot-api-key}",
        "PROMPTOT_MCP_CLIENT": "<promptot-mcp-client>"
      }
    }
  }
}
